ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| regex("(rclone(\\.exe)?\\s+.*\\b(mega:|mega\\.nz|mega\\.co\\.nz|--config\\s+\\S*mega)|vssadmin\\s+delete\\s+shadows|wbadmin\\s+delete\\s+catalog|bcdedit.*recoveryenabled\\s+no|bcdedit.*bootstatuspolicy\\s+ignoreallfailures|Win32_Shadowcopy.*Delete)", field=CommandLine, strict=false)
| case {
    regex("rclone", field=CommandLine, strict=false) | stage := "exfil";
    * | stage := "destroy";
  }
| groupBy([aid, ComputerName], function={ collect([stage, CommandLine, ImageFileName, @timestamp]) })
| array:contains("stage[]", value="exfil")
| array:contains("stage[]", value="destroy")
